const checks = [
  { domain: "apache.org", recordType: "SPF", query: "apache.org" },
  { domain: "apache.org", recordType: "DMARC", query: "_dmarc.apache.org" },
  { domain: "example.com", recordType: "SPF", query: "example.com" },
  { domain: "example.com", recordType: "DMARC", query: "_dmarc.example.com" }
];

return checks.map(check => ({
  json: check
}));

const items = $input.all();

// Convert each Google DNS API response into a normalized record.
const records = items.map((item) => {
  const data = item.json;
  const answers = Array.isArray(data.Answer) ? data.Answer : [];

  const questionName = Array.isArray(data.Question)
    ? (data.Question[0]?.name || "")
    : "";

  return {
    domain: questionName.replace(/\.$/, "").toLowerCase(),
    status: data.Status,
    txtRecords: answers
      .filter((answer) => Number(answer.type) === 16)
      .map((answer) => String(answer.data || "").trim())
  };
});

const domains = ["apache.org", "example.com"];

function gradeDomain(domain) {
  const normalizedDomain = domain.toLowerCase();

  const spfResponse = records.find(
    (record) => record.domain === normalizedDomain
  );

  const dmarcResponse = records.find(
    (record) => record.domain === `_dmarc.${normalizedDomain}`
  );

  const spfRecord = (spfResponse?.txtRecords || []).find(
    (record) => /^v=spf1(?:\s|$)/i.test(record)
  ) || null;

  const dmarcRecord = (dmarcResponse?.txtRecords || []).find(
    (record) => /^v=DMARC1\s*;/i.test(record)
  ) || null;

  const policyMatch = dmarcRecord
    ? dmarcRecord.match(/(?:^|;)\s*p\s*=\s*(none|quarantine|reject)\s*(?:;|$)/i)
    : null;

  const policy = policyMatch
    ? policyMatch[1].toLowerCase()
    : "missing";

  const reasons = [];
  let score = 0;

  // SPF scoring
  if (!spfRecord) {
    score += 2;
    reasons.push("SPF record missing");
  } else if (/\s-all\s*$/i.test(spfRecord)) {
    reasons.push("SPF uses hard-fail (-all)");
  } else {
    score += 1;
    reasons.push("SPF is present, but strict hard-fail (-all) is not confirmed");
  }

  // DMARC scoring: lower score means stronger posture.
  if (policy === "missing") {
    score += 3;
    reasons.push("DMARC record missing or policy invalid");
  } else if (policy === "none") {
    score += 3;
    reasons.push("DMARC is monitoring-only (p=none)");
  } else if (policy === "quarantine") {
    score += 1;
    reasons.push("DMARC quarantine policy is enforced");
  } else if (policy === "reject") {
    reasons.push("DMARC reject policy is enforced");
  }

  // Deterministic A-F grade.
  let grade;

  if (score === 0) {
    grade = "A";
  } else if (score === 1) {
    grade = "B";
  } else if (score === 2) {
    grade = "C";
  } else if (score === 3) {
    grade = "D";
  } else if (score === 4) {
    grade = "E";
  } else {
    grade = "F";
  }

  const severity = ["D", "E", "F"].includes(grade)
    ? "HIGH"
    : grade === "C"
      ? "MEDIUM"
      : "LOW";

  return {
    domain,
    spf: spfRecord || "Missing",
    dmarc: dmarcRecord || "Missing",
    dmarcPolicy: policy,
    score,
    grade,
    severity,
    reasons
  };
}

return domains.map((domain) => ({
  json: gradeDomain(domain)
}));

const items = $input.all();

const checks = items.map(item => {
  const data = item.json;
  const answers = Array.isArray(data.Answer) ? data.Answer : [];

  const questionName = data.Question?.[0]?.name || "";
  const isDMARC = questionName.toLowerCase().startsWith("_dmarc.");
  const domain = isDMARC
    ? questionName.slice(7).replace(/\.$/, "").toLowerCase()
    : questionName.replace(/\.$/, "").toLowerCase();

  const records = answers
    .filter(a => Number(a.type) === 16)
    .map(a => String(a.data || "").replace(/^"|"$/g, "").trim());

  return {
    domain,
    type: isDMARC ? "DMARC" : "SPF",
    records
  };
});

const results = ["apache.org", "example.com"].map(domain => {
  const spfCheck = checks.find(c => c.domain === domain && c.type === "SPF");
  const dmarcCheck = checks.find(c => c.domain === domain && c.type === "DMARC");

  const spf = spfCheck?.records.find(r => /^v=spf1/i.test(r)) || "Missing";
  const dmarc = dmarcCheck?.records.find(r => /^v=dmarc1/i.test(r)) || "Missing";

  const policy = dmarc.match(/(?:^|;)\s*p\s*=\s*(none|quarantine|reject)\s*(?:;|$)/i)?.[1]?.toLowerCase() || "missing";

  let score = 0;
  const reasons = [];

  if (spf === "Missing") {
    score += 2;
    reasons.push("SPF record missing");
  } else if (/\s-all\s*$/i.test(spf)) {
    reasons.push("SPF uses hard-fail (-all)");
  } else {
    score += 1;
    reasons.push("Strict SPF hard-fail not confirmed");
  }

  if (policy === "missing") {
    score += 3;
    reasons.push("DMARC missing or invalid");
  } else if (policy === "none") {
    score += 3;
    reasons.push("DMARC monitoring-only (p=none)");
  } else if (policy === "quarantine") {
    score += 1;
    reasons.push("DMARC quarantine enforced");
  } else {
    reasons.push("DMARC reject enforced");
  }

  const grade =
    score === 0 ? "A" :
    score === 1 ? "B" :
    score === 2 ? "C" :
    score === 3 ? "D" :
    score === 4 ? "E" : "F";

  return {
    domain,
    spf,
    dmarc,
    dmarcPolicy: policy,
    score,
    grade,
    severity: ["D", "E", "F"].includes(grade) ? "HIGH" : grade === "C" ? "MEDIUM" : "LOW",
    reasons
  };
});

return [{ json: { results } }];

const input = $input.all();

const results = input.flatMap(item => {
  const value = item.json.results;
  return Array.isArray(value) ? value : [item.json];
});

function redactSecrets(text) {
  return String(text)
    .replace(/\b\d{8,}:[A-Za-z0-9_-]{20,}\b/g, "[REDACTED_BOT_TOKEN]")
    .replace(/\b(bot|token|api[_-]?key|secret)\s*[:=]\s*\S+/gi, "$1=[REDACTED]");
}

const executionId = String($execution.id);

const checkedAt = $now
  .setZone("Asia/Kolkata")
  .toFormat("dd-LL-yyyy HH:mm:ss");

const rows = results.map(d => {
  const reasons = Array.isArray(d.reasons)
    ? d.reasons.map(r => String(r).replace(/[<>]/g, ""))
    : [];

  const grade = String(d.grade || "F");
  const severity = String(d.severity || "HIGH");

  const domain = String(d.domain || "Unknown");
  const spf = String(d.spf || "Missing");
  const dmarc = String(d.dmarc || "Missing");
  const dmarcPolicy = String(
    d.dmarcPolicy || d.policy || "missing"
  );

  const reasonsText = reasons.join("; ") || "No reasons provided";

  const highTag =
    ["D", "E", "F"].includes(grade.toUpperCase())
      ? " [HIGH]"
      : "";

  const reportSection = [
    `*Domain:* ${domain}`,
    `*SPF:* ${spf}`,
    `*DMARC:* ${dmarc}`,
    `*DMARC Policy:* ${dmarcPolicy}`,
    `*Grade:* ${grade}`,
    `*Severity:* ${severity}${highTag}`,
    `*Reasons:* ${reasonsText}`
  ].join("\n");

  const message = [
    "🔐 *NGP-053 — Email Security Posture Report*",
    "",
    reportSection,
    "",
    `*Execution ID:* ${executionId}`,
    `*Timestamp (IST):* ${checkedAt}`
  ].join("\n");

  const summary = `${domain}: Grade ${grade}, Severity ${severity}${highTag}`;

  const telegramMessage = [
    `🟣 NGP-053 | exec #${executionId} | ${checkedAt} | ${grade} / ${severity}${highTag} | ${summary}`,
    "",
    message
  ].join("\n");

  return {
    json: {
      execution_id: executionId,
      domain,
      grade,
      severity,
      spf_result: spf,
      dmarc_result: dmarc,
      reasons: reasonsText,
      checked_at: checkedAt,
      message: redactSecrets(telegramMessage)
    }
  };
});

return rows;

const items = $input.all();

function parseAIOutput(value) {
  let text = String(value ?? "").trim();

  text = text
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/, "")
    .trim();

  const parsed = JSON.parse(text);

  if (!parsed || !Array.isArray(parsed.results)) {
    throw new Error("AI output must contain a results array");
  }

  return parsed.results;
}

const aiResults = items.flatMap(item =>
  parseAIOutput(item.json.output)
);

const original = $("Code in JavaScript2").first().json.results;

if (!Array.isArray(original)) {
  throw new Error("Original DNS results are missing");
}

const originalByDomain = new Map(
  original.map(d => [String(d.domain).toLowerCase(), d])
);

const severityByGrade = {
  A: "LOW",
  B: "LOW",
  C: "MEDIUM",
  D: "HIGH",
  E: "CRITICAL",
  F: "CRITICAL"
};

const seen = new Set();

const output = aiResults.map(d => {
  const domain = String(d.domain || "").toLowerCase();
  const base = originalByDomain.get(domain);
  const grade = String(d.grade || "").toUpperCase();

  if (!base) {
    throw new Error(`Unexpected domain from AI: ${domain}`);
  }

  if (seen.has(domain)) {
    throw new Error(`Duplicate AI result: ${domain}`);
  }

  if (!severityByGrade[grade]) {
    throw new Error(`Invalid AI grade for ${domain}`);
  }

  seen.add(domain);

  return {
    json: {
      ...base,
      domain: String(base.domain),
      grade,
      severity: severityByGrade[grade],
      spf: String(base.spf || "Missing"),
      dmarc: String(base.dmarc || "Missing"),
      dmarcPolicy: String(
        base.dmarcPolicy || base.policy || "missing"
      ),
      reasons: Array.isArray(d.reasons)
        ? d.reasons.map(String)
        : []
    }
  };
});

if (seen.size !== originalByDomain.size) {
  throw new Error("AI did not return a result for every DNS domain");
}

return output;
